 "content": "def transform(grid):
    """Extend a solid separator by one cell beyond the adjacent object, in 8."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))

    # A full solid row/column is the separator. The non-background object on
    # either side determines where the parallel extension is drawn.
    separators = []
    for r, row in enumerate(grid):
        colors = set(row)
        if len(colors) == 1 and row[0] != bg:
            separators.append(("h", r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != bg:
            separators.append(("v", c, vals[0]))

    for orient, pos, line_color in separators:
        obj = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, line_color)]
        if not obj:
            continue
        if orient == "v":
            # Object should lie wholly to one side of the vertical separator.
            left = [(r, c) for r, c in obj if c < pos]
            right = [(r, c) for r, c in obj if c > pos]
            side = left if left and not right else right if right and not left else []
            if not side:
                continue
            target = min(c for r, c in side) - 1 if side is left else max(c for r, c in side) + 1
            if 0 <= target < w:
                for r in range(h):
                    out[r][target] = 8
        else:
            above = [(r, c) for r, c in obj if r < pos]
            below = [(r, c) for r, c in obj if r > pos]
            side = above if above and not below else below if below and not above else []
            if not side:
                continue
            target = min(r for r, c in side) - 1 if side is above else max(r for r, c in side) + 1
            if 0 <= target < h:
                for c in range(w):
                    out[target][c] = 8
    return out

